/**
 * The edge's package verification held to the engine's, vector by vector.
 *
 * docs/plugin-package-vectors.json is generated by the engine lane from the
 * engine's own code (crates/engine/src/plugins/vectors.rs): every case runs
 * here. The interim file test/fixtures/package-vectors.interim.json (made by
 * a scratch generator running the engine's signing.rs, manifest.rs,
 * package.rs and install.rs verbatim against the same serde_json, semver,
 * base64 and ring) stays until the generated file covers every case in it.
 */
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { isText } from "./checks";
import { JsonError, type JsonObject, canonicalJson, isObject, parseJsonText } from "./json";
import { BUILTIN_IDS, CATEGORIES, MAX_CATEGORIES, MAX_DESCRIPTION_LEN, MAX_ICON_BYTES, MAX_KEYWORDS, MAX_KEYWORD_LEN, MAX_LICENSE_LEN, MAX_NAME_LEN, MAX_SCREENSHOTS, MAX_URL_LEN, SCREENSHOT_TYPES, changelogNotes, checkListing } from "./listing";
import { idProblem, readManifest } from "./manifest";
import { MAX_BYTES, MAX_FILES, MAX_PACKAGE_BYTES, PackageRefusal, checkSignature, contentHash, signaturePayload, verifyPackage } from "./package";
import { plainPath } from "./paths";
import { MAX_RANGE_LENGTH, MAX_VERSION_LENGTH, comparePre, comparePrecedence, parseRange, parseSemver, parseVersion, satisfies } from "./semver";

/* eslint-disable @typescript-eslint/no-explicit-any */
const here = dirname(fileURLToPath(import.meta.url));
const load = (path: string): any => JSON.parse(readFileSync(resolve(here, path), "utf8"));
const engine = load("../../../docs/plugin-package-vectors.json");
const interim = load("../../test/fixtures/package-vectors.interim.json");

const fromB64 = (s: string): Uint8Array => new Uint8Array(Buffer.from(s, "base64"));
const hashesOf = (files: Record<string, string>) => new Map(Object.entries(files));
const value = (v: unknown) => parseJsonText(JSON.stringify(v));

const verdict = async (raw: Uint8Array): Promise<{ ok: true; [k: string]: unknown } | { ok: false; error: string }> => {
  try {
    const p = await verifyPackage(raw);
    return { ok: true, id: p.manifest.id, version: p.manifest.version, key: p.key, hash: p.hash, sha256: p.sha256, files: p.files.size };
  } catch (e) {
    if (!(e instanceof PackageRefusal)) throw e;
    return { ok: false, error: e.code };
  }
};

describe("engine vectors (docs/plugin-package-vectors.json)", () => {
  it("is the file the engine makes", () => {
    expect(engine.format).toBe("zeron-plugin-package-vectors:v1");
    expect(engine.package_format).toBe("zeron-plugin:v1");
    expect(engine.payload_prefix).toBe("zeron-plugin:v1\n");
  });

  it("limits, categories and built-in ids", () => {
    const l = engine.limits;
    expect([MAX_FILES, MAX_BYTES, MAX_PACKAGE_BYTES]).toEqual([Number(l.max_files), Number(l.max_bytes), Number(l.max_package_bytes)]);
    expect([MAX_CATEGORIES, MAX_DESCRIPTION_LEN, MAX_ICON_BYTES, MAX_KEYWORDS, MAX_KEYWORD_LEN, MAX_LICENSE_LEN, MAX_NAME_LEN, MAX_SCREENSHOTS, MAX_URL_LEN]).toEqual(
      ["max_categories", "max_description_len", "max_icon_bytes", "max_keywords", "max_keyword_len", "max_license_len", "max_name_len", "max_screenshots", "max_url_len"].map((k) => Number(l[k]))
    );
    expect([MAX_VERSION_LENGTH, MAX_RANGE_LENGTH, Number.MAX_SAFE_INTEGER]).toEqual([Number(l.max_version_len), Number(l.max_range_len), Number(l.max_number)]);
    expect(SCREENSHOT_TYPES).toEqual(typeof l.screenshot_types === "string" ? JSON.parse(l.screenshot_types) : l.screenshot_types);
    expect(CATEGORIES).toEqual(engine.categories);
    expect(BUILTIN_IDS).toEqual(engine.builtin_ids);
  });

  it("canonical JSON", () => {
    for (const v of engine.canonical_json) expect(canonicalJson(value(v.input)), v.name).toBe(v.canonical);
  });

  it("content hashes", async () => {
    for (const v of engine.content_hash) expect(await contentHash(value(v.manifest) as JsonObject, hashesOf(v.files)), v.name).toBe(v.hash);
  });

  it("signatures", async () => {
    for (const v of engine.signatures) {
      const manifest = value(v.manifest);
      const files = hashesOf(v.files);
      if (v.payload && isObject(manifest)) expect(signaturePayload(v.prefix, manifest, v.key, files), v.name).toBe(v.payload);
      const checked = await checkSignature(v.prefix, manifest, files);
      expect("valid" in checked ? "valid" : checked.invalid, v.name).toBe(v.result);
    }
  });

  it("packages", async () => {
    for (const v of engine.packages) {
      const got = await verdict(fromB64(v.package_b64));
      if (v.result === "ok") expect(got, v.name).toMatchObject({ ok: true, id: v.id, key: v.key, hash: v.content_hash, sha256: v.sha256 });
      else expect(got, v.name).toEqual({ ok: false, error: v.result });
    }
  });

  it("paths", () => {
    for (const v of engine.paths) expect(plainPath(v.path), JSON.stringify(v.path)).toBe(v.ok);
  });

  it("semver", () => {
    for (const v of engine.semver.parse) expect(parseVersion(v.input) !== undefined, JSON.stringify(v.input)).toBe(v.ok);
    const order: string[] = engine.semver.order;
    for (let i = 1; i < order.length; i++) expect(comparePrecedence(parseVersion(order[i - 1]!)!, parseVersion(order[i]!)!), `${order[i - 1]} < ${order[i]}`).toBe(-1);
    for (const v of engine.semver.compare) expect(comparePrecedence(parseVersion(v.a)!, parseVersion(v.b)!), `${v.a} vs ${v.b}`).toBe(v.cmp);
  });

  it("ranges", () => {
    for (const v of engine.ranges) {
      const range = parseRange(v.range);
      if (v.error) expect(range, JSON.stringify(v.range)).toBeUndefined();
      else expect(range !== undefined && satisfies(parseVersion(v.version)!, range), `${v.version} in ${JSON.stringify(v.range)}`).toBe(v.matches);
    }
  });

  it("listing rules", () => {
    for (const v of engine.listing) {
      const files = new Map(Object.entries(v.files_b64 as Record<string, string>).map(([p, b]) => [p, fromB64(b)]));
      const { problems, warnings } = checkListing(readManifest(value(v.manifest) as JsonObject), files, isText);
      const shape = (list: { rule: string; field: string | null; path: string | null }[]) => list.map((p) => ({ field: p.field, path: p.path, rule: p.rule }));
      expect(shape(problems), v.name).toEqual(v.problems);
      expect(shape(warnings), v.name).toEqual(v.warnings);
    }
  });

  it("changelog notes", () => {
    for (const v of engine.changelog) expect(changelogNotes(v.changelog, v.version) ?? null, v.version).toBe(v.notes);
  });
});

describe("interim vectors (engine code, scratch generator)", () => {
  it("canonical JSON", () => {
    for (const v of interim.canonical_json) {
      if (v.error) expect(() => parseJsonText(v.input), v.name).toThrow(JsonError);
      else expect(canonicalJson(parseJsonText(v.input)), v.name).toBe(v.canonical);
    }
  });

  it("content hashes", async () => {
    for (const v of interim.content_hash) {
      const manifest = parseJsonText(v.manifest);
      const files = typeof v.files === "string" ? JSON.parse(v.files) : v.files;
      expect(await contentHash(manifest as JsonObject, hashesOf(files)), v.name).toBe(v.hash);
    }
  });

  it("signatures", async () => {
    for (const v of interim.signatures) {
      const manifest = parseJsonText(v.manifest);
      const files = hashesOf(v.files);
      if (isObject(manifest)) {
        const signature = manifest.get("signature");
        const key = isObject(signature) && typeof signature.get("key") === "string" ? (signature.get("key") as string) : v.key;
        if (v.payload && key) expect(signaturePayload(v.prefix, manifest, key, files), v.name).toBe(v.payload);
      }
      const checked = await checkSignature(v.prefix, manifest, files);
      expect("valid" in checked ? "valid" : checked.invalid, v.name).toBe(v.result);
    }
  });

  it("paths", () => {
    for (const v of interim.paths) expect(plainPath(v.path), JSON.stringify(v.path)).toBe(v.ok);
  });

  it("manifests", () => {
    for (const v of interim.manifests) {
      const m = readManifest(parseJsonText(v.manifest) as JsonObject);
      expect(m.problem ?? null, v.name).toBe(v.problem);
      if ("id_error" in v) expect(idProblem(m.id) ?? null, v.name).toBe(v.id_error);
    }
  });

  it("packages", async () => {
    // The generated file's words: a bad id or a missing entry is `bad_manifest`.
    const word = (e: string) => (e === "bad_id" || e === "missing_entry" ? "bad_manifest" : e);
    for (const v of interim.packages) {
      const expected = v.result.ok ? v.result : { ok: false, error: word(v.result.error) };
      expect(await verdict(fromB64(v.package_b64)), v.name).toEqual(expected);
    }
  });

  it("semver parse, order and compare (u64 parts, as the semver crate)", () => {
    for (const v of interim.semver.parse) {
      const p = parseSemver(v.input);
      expect(p !== undefined, JSON.stringify(v.input)).toBe(v.ok);
      if (p && v.ok) {
        expect([String(p.major), String(p.minor), String(p.patch), p.pre.join("."), p.build.join(".")], v.input).toEqual([String(v.major), String(v.minor), String(v.patch), v.pre, v.build]);
      }
    }
    const compare = (a: string, b: string): number => {
      const x = parseSemver(a)!;
      const y = parseSemver(b)!;
      for (const k of ["major", "minor", "patch"] as const) if (x[k] !== y[k]) return x[k] < y[k] ? -1 : 1;
      return comparePre(x.pre, y.pre);
    };
    const order: string[] = interim.semver.order;
    for (let i = 1; i < order.length; i++) expect(compare(order[i - 1]!, order[i]!), `${order[i - 1]} < ${order[i]}`).toBe(-1);
    for (const v of interim.semver.compare) expect(compare(v.a, v.b), `${v.a} vs ${v.b}`).toBe(v.cmp);
  });
});
